from enum import Enum from fastapi import FastAPI class ModelName ( str , Enum ): alexnet = "alexnet" resnet = "resnet" lenet = "lenet" app = FastAPI () @app . get ( "/models/ {model_name} " ) async def get_model ( model_name : ModelName ): if model_name is ModelName . alexnet : return { "model_name" : model_name , "message" : "Deep Learning FTW!" } if model_name . value == "lenet" : return { "model_name" : model_name , "message" : "LeCNN all the images" } return { "model_name" : model_name , "message" : "Have some residuals" }
Tip
You could also access the value "lenet" with ModelName.lenet.value .
"lenet"
ModelName.lenet.value
You can return enum members from your path operation , even nested in a JSON body (e.g. a dict ).
dict
They will be converted to their corresponding values (strings in this case) before returning them to the client:
from enum import Enum from fastapi import FastAPI class ModelName ( str , Enum ): alexnet = "alexnet" resnet = "resnet" lenet = "lenet" app = FastAPI () @app . get ( "/models/ {model_name} " ) async def get_model ( model_name : ModelName ): if model_name is ModelName . alexnet : return { "model_name" : model_name , "message" : "Deep Learning FTW!" } if model_name . value == "lenet" : return { "model_name" : model_name , "message" : "LeCNN all the images" } return { "model_name" : model_name , "message" : "Have some residuals" }
from enum import Enum from fastapi import FastAPI class ModelName ( str , Enum ): alexnet = "alexnet" resnet = "resnet" lenet = "lenet" app = FastAPI () @app . get ( "/models/ {model_name} " ) async def get_model ( model_name : ModelName ): if model_name is ModelName . alexnet : return { "model_name" : model_name , "message" : "Deep Learning FTW!" } if model_name . value == "lenet" : return { "model_name" : model_name , "message" : "LeCNN all the images" } return { "model_name" : model_name , "message" : "Have some residuals" }
In your client you will get a JSON response like:
{ "model_name" : "alexnet" , "message" : "Deep Learning FTW!" }
{ "model_name" : "alexnet" , "message" : "Deep Learning FTW!" }

You can declare path parameters and request body at the same time.
FastAPI will recognize that the function parameters that match path parameters should be taken from the path , and that function parameters that are declared to be Pydantic models should be taken from the request body .
from fastapi import FastAPI from pydantic import BaseModel class Item ( BaseModel ): name : str description : str | None = None price : float tax : float | None = None app = FastAPI () @app . put ( "/items/ {item_id} " ) async def update_item ( item_id : int , item : Item ): return { "item_id" : item_id , ** item . model_dump ()}
from fastapi import FastAPI from pydantic import BaseModel class Item ( BaseModel ): name : str description : str | None = None price : float tax : float | None = None app = FastAPI () @app . put ( "/items/ {item_id} " ) async def update_item ( item_id : int , item : Item ): return { "item_id" : item_id , ** item . model_dump ()}

To exclude a query parameter from the generated OpenAPI schema (and thus, from the automatic documentation systems), set the parameter include_in_schema of Query to False :
include_in_schema
Query
False
from typing import Annotated from fastapi import FastAPI , Query app = FastAPI () @app . get ( "/items/" ) async def read_items ( hidden_query : Annotated [ str | None , Query ( include_in_schema = False )] = None , ): if hidden_query : return { "hidden_query" : hidden_query } else : return { "hidden_query" : "Not found" }
from typing import Annotated from fastapi import FastAPI , Query app = FastAPI () @app . get ( "/items/" ) async def read_items ( hidden_query : Annotated [ str | None , Query ( include_in_schema = False )] = None , ): if hidden_query : return { "hidden_query" : hidden_query } else : return { "hidden_query" : "Not found" }
Tip
Prefer to use the Annotated version if possible.
Annotated
from fastapi import FastAPI , Query app = FastAPI () @app . get ( "/items/" ) async def read_items ( hidden_query : str | None = Query ( default = None , include_in_schema = False ), ): if hidden_query : return { "hidden_query" : hidden_query } else : return { "hidden_query" : "Not found" }
from fastapi import FastAPI , Query app = FastAPI () @app . get ( "/items/" ) async def read_items ( hidden_query : str | None = Query ( default = None , include_in_schema = False ), ): if hidden_query : return { "hidden_query" : hidden_query } else : return { "hidden_query" : "Not found" }

Here's an example path operation with parameters using some of the above types.
from datetime import datetime , time , timedelta from typing import Annotated from uuid import UUID from fastapi import Body , FastAPI app = FastAPI () @app . put ( "/items/ {item_id} " ) async def read_items ( item_id : UUID , start_datetime : Annotated [ datetime , Body ()], end_datetime : Annotated [ datetime , Body ()], process_after : Annotated [ timedelta , Body ()], repeat_at : Annotated [ time | None , Body ()] = None , ): start_process = start_datetime + process_after duration = end_datetime - start_process return { "item_id" : item_id , "start_datetime" : start_datetime , "end_datetime" : end_datetime , "process_after" : process_after , "repeat_at" : repeat_at , "start_process" : start_process , "duration" : duration , }
from datetime import datetime , time , timedelta from typing import Annotated from uuid import UUID from fastapi import Body , FastAPI app = FastAPI () @app . put ( "/items/ {item_id} " ) async def read_items ( item_id : UUID , start_datetime : Annotated [ datetime , Body ()], end_datetime : Annotated [ datetime , Body ()], process_after : Annotated [ timedelta , Body ()], repeat_at : Annotated [ time | None , Body ()] = None , ): start_process = start_datetime + process_after duration = end_datetime - start_process return { "item_id" : item_id , "start_datetime" : start_datetime , "end_datetime" : end_datetime , "process_after" : process_after , "repeat_at" : repeat_at , "start_process" : start_process , "duration" : duration , }
Tip
Prefer to use the Annotated version if possible.
