APIRouter
You import it and create an "instance" the same way you would with the class FastAPI :
FastAPI
from fastapi import APIRouter router = APIRouter () @router . get ( "/users/" , tags = [ "users" ]) async def read_users (): return [{ "username" : "Rick" }, { "username" : "Morty" }] @router . get ( "/users/me" , tags = [ "users" ]) async def read_user_me (): return { "username" : "fakecurrentuser" } @router . get ( "/users/ {username} " , tags = [ "users" ]) async def read_user ( username : str ): return { "username" : username }
from fastapi import APIRouter router = APIRouter () @router . get ( "/users/" , tags = [ "users" ]) async def read_users (): return [{ "username" : "Rick" }, { "username" : "Morty" }] @router . get ( "/users/me" , tags = [ "users" ]) async def read_user_me (): return { "username" : "fakecurrentuser" } @router . get ( "/users/ {username} " , tags = [ "users" ]) async def read_user ( username : str ): return { "username" : username }

If you don't want to serve a fallback file for missing frontend paths, use fallback=None :
fallback=None
from fastapi import FastAPI app = FastAPI () app . frontend ( "/" , directory = "dist" , fallback = None )
from fastapi import FastAPI app = FastAPI () app . frontend ( "/" , directory = "dist" , fallback = None )
Then missing frontend paths return the normal 404 .
404

uvicorn
In your FastAPI application, import and run uvicorn directly:
uvicorn
import uvicorn from fastapi import FastAPI app = FastAPI () @app . get ( "/" ) def root (): a = "a" b = "b" + a return { "hello world" : b } if __name__ == "__main__" : uvicorn . run ( app , host = "0.0.0.0" , port = 8000 )
import uvicorn from fastapi import FastAPI app = FastAPI () @app . get ( "/" ) def root (): a = "a" b = "b" + a return { "hello world" : b } if __name__ == "__main__" : uvicorn . run ( app , host = "0.0.0.0" , port = 8000 )

You can create your own custom response class, inheriting from Response and using it.
Response
For example, let's say that you want to use orjson with some settings.
orjson
Let's say you want it to return indented and formatted JSON, so you want to use the orjson option orjson.OPT_INDENT_2 .
orjson.OPT_INDENT_2
You could create a CustomORJSONResponse . The main thing you have to do is create a Response.render(content) method that returns the content as bytes :
CustomORJSONResponse
Response.render(content)
bytes
from typing import Any import orjson from fastapi import FastAPI , Response app = FastAPI () class CustomORJSONResponse ( Response ): media_type = "application/json" def render ( self , content : Any ) -> bytes : assert orjson is not None , "orjson must be installed" return orjson . dumps ( content , option = orjson . OPT_INDENT_2 ) @app . get ( "/" , response_class = CustomORJSONResponse ) async def main (): return { "message" : "Hello World" }
from typing import Any import orjson from fastapi import FastAPI , Response app = FastAPI () class CustomORJSONResponse ( Response ): media_type = "application/json" def render ( self , content : Any ) -> bytes : assert orjson is not None , "orjson must be installed" return orjson . dumps ( content , option = orjson . OPT_INDENT_2 ) @app . get ( "/" , response_class = CustomORJSONResponse ) async def main (): return { "message" : "Hello World" }
Now instead of returning:
{ "message" : "Hello World" }
{ "message" : "Hello World" }
...this response will return:
{ "message" : "Hello World" }
{ "message" : "Hello World" }
Of course, you will probably find much better ways to take advantage of this than formatting JSON. 😉

You might want to have some predefined responses that apply to many path operations , but you want to combine them with custom responses needed by each path operation .
For those cases, you can use the Python technique of "unpacking" a dict with **dict_to_unpack :
dict
**dict_to_unpack
old_dict = { "old key" : "old value" , "second old key" : "second old value" , } new_dict = { ** old_dict , "new key" : "new value" }
old_dict = { "old key" : "old value" , "second old key" : "second old value" , } new_dict = { ** old_dict , "new key" : "new value" }
Here, new_dict will contain all the key-value pairs from old_dict plus the new key-value pair:
new_dict
old_dict
{ "old key" : "old value" , "second old key" : "second old value" , "new key" : "new value" , }
{ "old key" : "old value" , "second old key" : "second old value" , "new key" : "new value" , }
You can use that technique to reuse some predefined responses in your path operations and combine them with additional custom ones.
For example:
from fastapi import FastAPI from fastapi.responses import FileResponse from pydantic import BaseModel class Item ( BaseModel ): id : str value : str responses = { 404 : { "description" : "Item not found" }, 302 : { "description" : "The item was moved" }, 403 : { "description" : "Not enough privileges" }, } app = FastAPI () @app . get ( "/items/ {item_id} " , response_model = Item , responses = { ** responses , 200 : { "content" : { "image/png" : {}}}}, ) async def read_item ( item_id : str , img : bool | None = None ): if img : return FileResponse ( "image.png" , media_type = "image/png" ) else : return { "id" : "foo" , "value" : "there goes my hero" }
from fastapi import FastAPI from fastapi.responses import FileResponse from pydantic import BaseModel class Item ( BaseModel ): id : str value : str responses = { 404 : { "description" : "Item not found" }, 302 : { "description" : "The item was moved" }, 403 : { "description" : "Not enough privileges" }, } app = FastAPI () @app . get ( "/items/ {item_id} " , response_model = Item , responses = { ** responses , 200 : { "content" : { "image/png" : {}}}}, ) async def read_item ( item_id : str , img : bool | None = None ): if img : return FileResponse ( "image.png" , media_type = "image/png" ) else : return { "id" : "foo" , "value" : "there goes my hero" }

In Python there's a way to make an instance of a class a "callable".
Not the class itself (which is already a callable), but an instance of that class.
To do that, we declare a method __call__ :
__call__
from typing import Annotated from fastapi import Depends , FastAPI app = FastAPI () class FixedContentQueryChecker : def __init__ ( self , fixed_content : str ): self . fixed_content = fixed_content def __call__ ( self , q : str = "" ): if q : return self . fixed_content in q return False checker = FixedContentQueryChecker ( "bar" ) @app . get ( "/query-checker/" ) async def read_query_check ( fixed_content_included : Annotated [ bool , Depends ( checker )]): return { "fixed_content_in_query" : fixed_content_included }
from typing import Annotated from fastapi import Depends , FastAPI app = FastAPI () class FixedContentQueryChecker : def __init__ ( self , fixed_content : str ): self . fixed_content = fixed_content def __call__ ( self , q : str = "" ): if q : return self . fixed_content in q return False checker = FixedContentQueryChecker ( "bar" ) @app . get ( "/query-checker/" ) async def read_query_check ( fixed_content_included : Annotated [ bool , Depends ( checker )]): return { "fixed_content_in_query" : fixed_content_included }
Tip
Prefer to use the Annotated version if possible.
Annotated
from fastapi import Depends , FastAPI app = FastAPI () class FixedContentQueryChecker : def __init__ ( self , fixed_content : str ): self . fixed_content = fixed_content def __call__ ( self , q : str = "" ): if q : return self . fixed_content in q return False checker = FixedContentQueryChecker ( "bar" ) @app . get ( "/query-checker/" ) async def read_query_check ( fixed_content_included : bool = Depends ( checker )): return { "fixed_content_in_query" : fixed_content_included }
from fastapi import Depends , FastAPI app = FastAPI () class FixedContentQueryChecker : def __init__ ( self , fixed_content : str ): self . fixed_content = fixed_content def __call__ ( self , q : str = "" ): if q : return self . fixed_content in q return False checker = FixedContentQueryChecker ( "bar" ) @app . get ( "/query-checker/" ) async def read_query_check ( fixed_content_included : bool = Depends ( checker )): return { "fixed_content_in_query" : fixed_content_included }
In this case, this __call__ is what FastAPI will use to check for additional parameters and sub-dependencies, and this is what will be called to pass a value to the parameter in your path operation function later.
__call__

And now, we can use __init__ to declare the parameters of the instance that we can use to "parameterize" the dependency:
__init__
